 const send=(event,down)=>{if(!active())return;const b=layer.getBoundingClientRect();nativeRequest('pointer',{x:Math.round((event.clientX-b.left)*1024/b.width),y:Math.round((event.clientY-b.top)*600/b.height),down});};
 layer.onpointerdown=e=>{e.preventDefault();e.stopPropagation();if(e.button>0)return;clearTimeout(hoverTimer);flushWheel();pressed=true;layer.setPointerCapture?.(e.pointerId);send(e,1);};
