 layer.onwheel=e=>{e.preventDefault();e.stopPropagation();if(!active())return;const b=layer.getBoundingClientRect();wheelPoint={x:Math.round((e.clientX-b.left)*1024/b.width),y:Math.round((e.clientY-b.top)*600/b.height)};wheelDelta+=Math.round(e.deltaY*(e.deltaMode===1?24:e.deltaMode===2?600:1));const delay=60-(Date.now()-lastWheel);if(delay<=0)flushWheel();else if(!wheelTimer)wheelTimer=setTimeout(flushWheel,delay);};
