function field(title,value,onChange,options={}){const w=element('label','field'),span=element('span','',title);const input=element(options.multiline?'textarea':'input');input.value=value??'';if(options.type)input.type=options.type;if(options.max)input.maxLength=options.max;input.addEventListener('change',()=>onChange(input.value,input));w.append(span,input);if(options.help)w.append(element('small','',options.help));return w;}
