 screen.onwheel=event=>{if(pickMode||tablet.modal||tablet.fullscreen)return;const bounds=screen.getBoundingClientRect(),x=(event.clientX-bounds.left)*1024/bounds.width,y=(event.clientY-bounds.top)*600/bounds.height;const inViewport=page==='settings'?y>=146&&y<=504:page==='files'?x<600&&y>=208&&y<=504:page==='telemetry'?y>=192&&y<=477:page==='console'?y>=202&&y<=448:false;if(inViewport){event.preventDefault();tabletAction('scroll',event.deltaY);}};
 let drag=null;
 screen.onpointerdown=event=>{if(pickMode||tablet.modal||tablet.fullscreen||!TabletModel.scrollMax(tablet)||event.button>0)return;const bounds=screen.getBoundingClientRect(),x=(event.clientX-bounds.left)*1024/bounds.width,y=(event.clientY-bounds.top)*600/bounds.height;const viewport={settings:['settings-content',66,146,504],files:['file-list',128,208,504],telemetry:['charts',112,192,477]}[page];if(!viewport||y<viewport[2]||y>viewport[3]||(page==='files'&&x>600))return;drag={y:event.clientY,scale:600/bounds.height,scroll:tablet.scroll,moved:false,viewport,pointer:event.pointerId};};
 screen.onpointermove=event=>{if(!drag)return;const delta=(drag.y-event.clientY)*drag.scale;if(!drag.moved&&Math.abs(delta)<6)return;drag.moved=true;event.preventDefault();screen.setPointerCapture?.(drag.pointer);const group=screen.querySelector('g[clip-path="url(#'+drag.viewport[0]+')"]>g');const scroll=Math.max(0,Math.min(TabletModel.scrollMax(tablet),drag.scroll+delta));group?.setAttribute('transform','translate(0 '+(drag.viewport[1]-scroll)+')');};
