 const original=M.create(project.base_theme).palette[picked.key],reset=element('button','reset-color','Reset '+labelize(picked.key)+' to Studio default');reset.onclick=()=>{const key=picked.key;if(project.palette[key].toUpperCase()===original.toUpperCase()&&!invalid.has(key)){tell(labelize(key)+' already uses the Studio default.');return;}commit(()=>{project.palette[key]=original;invalid.delete(key);});tell('Reset '+labelize(key)+'. Undo restores your color.');};
